/*
 * guatiao_channel -- a two-way stream of bytes between a host and a
 * provider: the `channel` and `channel_sink` object kinds' tables.
 *
 * GENERATED BY cbindgen, from build.rs, by expanding #[guatiao::kind].
 * DO NOT EDIT BY HAND. Regenerate with:
 *   GUATIAO_WRITE_HEADER=1 cargo build -p guatiao-channel --features c-header
 *
 * A provider fills a channel_vtable and hands it back as a guatiao_object;
 * a host fills a channel_sink_vtable and hands it in. `header.struct_size`
 * is sizeof the table, `header.floor_hash` the *_FLOOR_HASH macro beside
 * it, and `destroy` comes first, called by whoever holds the object last.
 *
 * The rules both sides keep:
 *  - send and receive return once the other side has taken the message;
 *    neither answers GUATIAO_ERR_BUSY or times out. A host never waits
 *    inside receive for its own send to return: a provider whose output
 *    depends on its input would deadlock on a full queue.
 *  - messages keep their call order per direction. The provider makes
 *    every call on the sink (receive and closed) from one thread at a
 *    time, and none while another is running.
 *  - the status in close(status, reason) and closed(status, reason) is a
 *    guatiao_status value: GUATIAO_OK is the normal end, anything else an
 *    error status.
 *  - the reason is UTF-8 text for people, lent for the call and empty
 *    when there is none: the host's reason for giving up, the provider's
 *    failure. Logs only; no one parses it. A gone sink or a destroyed
 *    channel says the same as GUATIAO_OK and an empty reason.
 *  - after close (or destroying the channel, close(GUATIAO_OK, "")), send
 *    answers GUATIAO_ERR_GONE, also a send that was waiting for room, and
 *    none is taken once close has returned. The provider calls closed
 *    with the host's status once, unless it already had, then never the
 *    sink again. close and destroy return without waiting for a receive
 *    that is still running.
 *  - after closed from the provider, send answers GUATIAO_ERR_GONE.
 *  - a host that takes nothing more answers GUATIAO_ERR_GONE from receive;
 *    any error from receive ends the stream: closed with that status, and
 *    no message still queued is delivered.
 *  - a C provider's close and a C host's closed answer GUATIAO_OK: they cannot fail, and
 *    any other answer is a bug the provider's proxy panics on.
 *  - a provider's library refuses to unload (GUATIAO_ERR_BUSY) while a
 *    thread of its own is still inside a call on the sink.
 */


#ifndef GUATIAO_CHANNEL_H
#define GUATIAO_CHANNEL_H

#include <stdarg.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <guatiao.h>

/*
 The kind's function table: a header, then one slot per method,
 in declaration order.
 */
typedef struct channel_vtable {
  guatiao_kind_header header;
  void (*destroy)(void *ctx);
  guatiao_status (*send)(void *ctx, guatiao_bytes bytes, guatiao_provider_error *err);
  guatiao_status (*close)(void *ctx, uint32_t status, guatiao_str reason);
} channel_vtable;
/*
 FNV-1a over the shape and every slot's signature, as a
 literal, so a C header generator can render it: what a C
 implementation writes into the table's header.
 */
#define channel_vtable_FLOOR_HASH 3787630980

/*
 The kind's function table: a header, then one slot per method,
 in declaration order.
 */
typedef struct channel_sink_vtable {
  guatiao_kind_header header;
  void (*destroy)(void *ctx);
  guatiao_status (*receive)(void *ctx, guatiao_bytes bytes, guatiao_provider_error *err);
  guatiao_status (*closed)(void *ctx, uint32_t status, guatiao_str reason);
} channel_sink_vtable;
/*
 FNV-1a over the shape and every slot's signature, as a
 literal, so a C header generator can render it: what a C
 implementation writes into the table's header.
 */
#define channel_sink_vtable_FLOOR_HASH 4115266557

#endif  /* GUATIAO_CHANNEL_H */
